import{_ as t,o,c as d,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"Skill-Driven Multi-Model Studio Image Pipeline (agy + codex + Qwen Worker)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/06-ai-media-and-video-studio/skill-driven-multi-model-studio-image/spec.md","filePath":"feature/modules/06-ai-media-and-video-studio/skill-driven-multi-model-studio-image/spec.md"}'),i={name:"feature/modules/06-ai-media-and-video-studio/skill-driven-multi-model-studio-image/spec.md"};function n(r,e,l,c,s,g){return o(),d("div",null,[...e[0]||(e[0]=[a(`<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="skill-driven-multi-model-studio-image-pipeline-agy-codex-qwen-worker" tabindex="-1">Skill-Driven Multi-Model Studio Image Pipeline (<code>agy</code> + <code>codex</code> + Qwen Worker) <a class="header-anchor" href="#skill-driven-multi-model-studio-image-pipeline-agy-codex-qwen-worker" aria-label="Permalink to &quot;Skill-Driven Multi-Model Studio Image Pipeline (\`agy\` + \`codex\` + Qwen Worker)&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>skill-driven-multi-model-studio-image</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>06-ai-media-and-video-studio</code> — AI Commercial Image, Product Video &amp; Conversational Video Studio</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator</code> (<code>Guest</code> → <code>401</code>; <code>Client</code> / <code>Admin</code> outside studio scope → <code>403</code>)</td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-7-generate-ambassador/spec.html">FR 3.7.7 — Generate Ambassador</a> · <a href="./../../../srs/06-ai-features/3-7-8-view-image-style-template/spec.html">FR 3.7.8 — View Image Style Template</a> · <a href="./../../../srs/06-ai-features/3-7-9-generate-image/spec.html">FR 3.7.9 — Generate Image</a></td></tr><tr><td style="text-align:left;"><strong>Related Module</strong></td><td style="text-align:left;"><a href="./../commercial-image-and-qwen-ambassador/spec.html">Commercial Image &amp; Qwen Ambassador</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Proposed — Ready for Implementation</td></tr></tbody></table><hr><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver a unified, production-ready, skill-driven image generation and composition pipeline in <code>brandhub-ai-service</code> that runs <strong>alongside</strong> (without replacing) the existing Vast.ai <strong>Qwen Image 2.1 ComfyUI</strong> GPU worker:</p><ol><li><strong>Creative Orchestration + Multi-Model Image Generation (<code>agy</code> &amp; <code>codex</code>):</strong><ul><li><strong>Antigravity CLI (<code>agy</code>)</strong>: Uses <code>AGY_MODEL=gemini-4-neon-low</code> as the Creative Director orchestrator to refine prompts with BrandHub domain skills and dispatches to <code>AGY_IMG=gemini-3.8-flash-low</code> (<code>image-generator</code>) for fast, high-fidelity generation (<code>~30–40s</code>).</li><li><strong>Codex OAuth (<code>codex</code>)</strong>: Uses <code>GPT_MODEL=gpt-6-sol-light</code> (mapped to <code>model=&quot;gpt-6-sol&quot;</code> with <code>reasoning.effort=&quot;low&quot;</code> on the Codex Responses endpoint) as the Creative Director orchestrator, dispatching <code>image_generation</code> to <code>GPT_IMG_FAST=gpt-image-2.6-flare</code> (fast daily/layout iteration) or <code>GPT_IMG_NOR=gpt-image-2.6-sunburst</code> (high-detail commercial visuals), with real progressive <code>partial_image_b64</code> streaming.</li></ul></li><li><strong>Zero-Turn Python Skill Injection (9 Studio Skills + Creative Director):</strong><ul><li>Stores 10 modular skills in <code>brandhub-ai-service/.agents/skills/</code> (<code>agency-creative-director</code> + 9 specialized skills). Python reads and injects <code>agency-creative-director/SKILL.md</code> + the matched task <code>SKILL.md</code> + workspace <code>brand_context</code> directly into the first orchestrator turn so quality rises sharply without paying 15–25s of multi-turn disk reads.</li></ul></li><li><strong>Complete Qwen Studio Workflow Coverage (<code>wf2</code> &amp; <code>wf3</code>):</strong><ul><li>Wires the missing Vast.ai Qwen worker endpoints (<code>/api/v1/wf2/pose_match</code> and <code>/api/v1/wf3/outfit_change</code>) into <code>brandhub-ai-service</code> and <code>brandhub-business-service</code> so <code>pose-match</code> and <code>virtual-tryon</code> no longer detour through 3-image <code>wf1_ad_composer</code>.</li></ul></li><li><strong>Studio Node <code>model</code> + <code>effort</code> Controls &amp; KSampler Progress UX:</strong><ul><li>Adds <code>model</code> and <code>effort</code> selectors to Studio nodes (<code>StudioNodeInspectorDock.tsx</code> &amp; <code>StudioSimpleMode.tsx</code>) and renders a ComfyUI <strong>KSampler-style</strong> multi-step progress visualizer on <code>outputNode</code> and the Simple Mode output panel.</li></ul></li><li><strong>Hybrid S3 / Local Storage:</strong><ul><li>Reuses <code>app/services/image/storage_service.py</code> (<code>store_generated_image</code>) across all providers, supporting EC2 IAM Instance Profile (IMDSv2) S3 in production and automatic <code>/static/generated/</code> fallback locally.</li></ul></li></ol><hr><h2 id="_2-approaches-considered-design-decisions" tabindex="-1">2. Approaches Considered &amp; Design Decisions <a class="header-anchor" href="#_2-approaches-considered-design-decisions" aria-label="Permalink to &quot;2. Approaches Considered &amp; Design Decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Approach</th><th style="text-align:left;">Summary</th><th style="text-align:left;">Tradeoff</th><th style="text-align:left;">Decision</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. Python Zero-Turn Skill Injection + Hybrid Coexisting Providers</strong></td><td style="text-align:left;">Python pre-loads <code>agency-creative-director</code> + task <code>SKILL.md</code> + workspace brand context into the single orchestrator call; <code>agy</code>, <code>codex</code>, and <code>qwen-studio</code> coexist behind <code>studio_image.py</code> + <code>storage_service.py</code>.</td><td style="text-align:left;">Slightly larger single-turn system prompt (~2–3K tokens), zero extra tool turns.</td><td style="text-align:left;"><strong>Selected</strong></td></tr><tr><td style="text-align:left;"><strong>B. Multi-Turn CLI Skill Discovery</strong></td><td style="text-align:left;">Let <code>agy</code>/<code>codex</code> run shell/file tools to browse <code>.agents/skills/</code> on each request.</td><td style="text-align:left;">Adds 15–25s latency and unpredictable sandbox permission retries.</td><td style="text-align:left;">Rejected</td></tr><tr><td style="text-align:left;"><strong>C. Replace Vast.ai Qwen Completely</strong></td><td style="text-align:left;">Route everything to <code>agy</code>/<code>codex</code> and drop ComfyUI.</td><td style="text-align:left;">Loses deterministic ComfyUI LoRA + exact pixel-preserving product/pose/outfit locking when GPU worker is online.</td><td style="text-align:left;">Rejected</td></tr></tbody></table><h3 id="architect-s-default-calls-confirm-with-product-owner" tabindex="-1">Architect&#39;s Default Calls (Confirm with Product Owner) <a class="header-anchor" href="#architect-s-default-calls-confirm-with-product-owner" aria-label="Permalink to &quot;Architect&#39;s Default Calls (Confirm with Product Owner)&quot;">​</a></h3><ul><li><strong>Studio Node <code>model</code> Options (<code>StudioModelId</code>):</strong> <code>auto</code> (default — uses <code>AI_IMAGE_PROVIDER</code> / <code>qwen-studio</code> fallback), <code>qwen-studio</code>, <code>agy</code>, <code>gpt-image-2.6-flare</code>, <code>gpt-image-2.6-sunburst</code>. Availability is fetched dynamically from <code>GET /api/v1/ai/image/models</code> so unavailable providers are disabled with a clear reason.</li><li><strong>Studio Node <code>effort</code> Options (<code>StudioEffortLevel</code>):</strong> <code>low</code> (default, <code>~25–40s</code>), <code>medium</code> (<code>~40–60s</code>), <code>high</code> (<code>~55–80s</code>). Maps to <code>reasoning.effort</code> on <code>gpt-6-sol</code> (<code>codex</code>), <code>AGY_IMG=gemini-3.8-flash-low</code> (<code>low</code> fast pass) vs <code>AGY_MODEL=gemini-4-neon-low</code> (<code>medium</code>/<code>high</code> skill-enriched) on <code>agy</code>, and <code>steps</code> (<code>20</code>/<code>25</code>/<code>32</code>) on <code>qwen-studio</code>.</li><li><strong>Multi-Reference Guard:</strong> <code>qwen-studio</code>, <code>gpt-image-2.6-flare</code>, and <code>gpt-image-2.6-sunburst</code> accept 1–3 reference images directly; when <code>agy</code> is selected for a multi-image workflow (<code>ad-composer</code>, <code>pose-match</code>, <code>virtual-tryon</code>), the UI shows a non-blocking hint that <code>agy</code> synthesizes via prompt direction rather than pixel-exact LoRA locking.</li></ul><hr><h2 id="_3-nine-active-skills-creative-director-mapping" tabindex="-1">3. Nine Active Skills + Creative Director Mapping <a class="header-anchor" href="#_3-nine-active-skills-creative-director-mapping" aria-label="Permalink to &quot;3. Nine Active Skills + Creative Director Mapping&quot;">​</a></h2><p>All skill files live in <code>brandhub-ai-service/.agents/skills/</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Folder</th><th style="text-align:left;">Role</th><th style="text-align:left;">Injected When</th></tr></thead><tbody><tr><td style="text-align:left;"><code>agency-creative-director/</code> (<code>SKILL.md</code> + <code>references/</code>)</td><td style="text-align:left;">Master Art Director &amp; prompt synthesizer</td><td style="text-align:left;"><strong>Always</strong> injected as base system directive</td></tr><tr><td style="text-align:left;"><code>product-posing/</code></td><td style="text-align:left;">Subject-product interaction &amp; hand/grip realism</td><td style="text-align:left;"><code>ad-composer</code>, product showcase prompts</td></tr><tr><td style="text-align:left;"><code>virtual-try-on/</code></td><td style="text-align:left;">Garment fit, fabric drape, body-contour realism</td><td style="text-align:left;"><code>virtual-tryon</code>, <code>wf3_outfit_change</code></td></tr><tr><td style="text-align:left;"><code>outfit-replacement/</code></td><td style="text-align:left;">Clean apparel swap preserving face &amp; pose</td><td style="text-align:left;"><code>virtual-tryon</code>, color/outfit <code>refine</code></td></tr><tr><td style="text-align:left;"><code>pose-director/</code></td><td style="text-align:left;">Skeletal alignment, camera angle, framing</td><td style="text-align:left;"><code>pose-match</code>, <code>wf2_pose_match</code></td></tr><tr><td style="text-align:left;"><code>product-photography/</code></td><td style="text-align:left;">Studio lighting, surface reflections, packaging fidelity</td><td style="text-align:left;">Product-only or commercial packshots</td></tr><tr><td style="text-align:left;"><code>background-replacement/</code></td><td style="text-align:left;">Seamless scene/environment compositing &amp; light match</td><td style="text-align:left;"><code>ad-composer</code>, background <code>refine</code></td></tr><tr><td style="text-align:left;"><code>advertising-key-visual/</code></td><td style="text-align:left;">Hero campaign composition, negative space, focal hierarchy</td><td style="text-align:left;">Key-visual / campaign banner requests</td></tr><tr><td style="text-align:left;"><code>commercial-retouching/</code></td><td style="text-align:left;">Skin/texture polish, color grading, artifact removal</td><td style="text-align:left;"><code>refine</code> mode &amp; <code>high</code> effort commercial output</td></tr><tr><td style="text-align:left;"><code>brand-consistency/</code></td><td style="text-align:left;">Enforces workspace palette, tone, mood &amp; visual identity</td><td style="text-align:left;"><strong>Always</strong> when workspace <code>brand_context</code> exists</td></tr></tbody></table><hr><h2 id="_4-environment-configuration-contract" tabindex="-1">4. Environment Configuration Contract <a class="header-anchor" href="#_4-environment-configuration-contract" aria-label="Permalink to &quot;4. Environment Configuration Contract&quot;">​</a></h2><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Primary image provider for unified Studio endpoint: agy | codex | auto</span></span>
<span class="line"><span>AI_IMAGE_PROVIDER=agy</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Antigravity CLI (agy)</span></span>
<span class="line"><span>AGY_CLI_PATH=</span></span>
<span class="line"><span>AGY_MODEL=gemini-4-neon-low</span></span>
<span class="line"><span>AGY_IMG=gemini-3.8-flash-low</span></span>
<span class="line"><span>AGY_TIMEOUT_SECONDS=120</span></span>
<span class="line"><span>AGY_MAX_CONCURRENCY=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Codex OAuth Image Provider</span></span>
<span class="line"><span>CODEX_OAUTH_ACCESS_TOKEN=</span></span>
<span class="line"><span>CODEX_AUTH_JSON_PATH=</span></span>
<span class="line"><span>GPT_MODEL=gpt-6-sol-light</span></span>
<span class="line"><span>GPT_IMG_FAST=gpt-image-2.6-flare</span></span>
<span class="line"><span>GPT_IMG_NOR=gpt-image-2.6-sunburst</span></span>
<span class="line"><span>CODEX_TIMEOUT_SECONDS=180</span></span></code></pre></div><hr><h2 id="_5-mandatory-ui-ux-i18n-vi-en-light-dark-mode-requirements" tabindex="-1">5. Mandatory UI/UX, i18n (<code>vi</code> + <code>en</code>) &amp; Light/Dark Mode Requirements <a class="header-anchor" href="#_5-mandatory-ui-ux-i18n-vi-en-light-dark-mode-requirements" aria-label="Permalink to &quot;5. Mandatory UI/UX, i18n (\`vi\` + \`en\`) &amp; Light/Dark Mode Requirements&quot;">​</a></h2><ol><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code> key-parallel):</strong><ul><li>Every new UI label, model name, effort option, skill badge, KSampler stage title, and error message MUST be added simultaneously to <code>brandhub-web/src/i18n/locales/vi/aiStudio.json</code> and <code>brandhub-web/src/i18n/locales/en/aiStudio.json</code> under: <ul><li><code>aiStudio.studio.models.*</code> (<code>label</code>, <code>auto</code>, <code>qwenStudio</code>, <code>agy</code>, <code>gptFlare</code>, <code>gptSunburst</code>, <code>unavailableHint</code>, <code>approxRefHint</code>)</li><li><code>aiStudio.studio.effort.*</code> (<code>label</code>, <code>low</code>, <code>medium</code>, <code>high</code>)</li><li><code>aiStudio.studio.ksampler.*</code> (<code>title</code>, <code>stageOrchestrating</code>, <code>stageComposing</code>, <code>stageSampling</code>, <code>stageStoring</code>, <code>stageCompleted</code>, <code>expandedPrompt</code>, <code>stepLabel</code>)</li></ul></li><li>Zero hardcoded Vietnamese or English strings in JSX/TSX.</li></ul></li><li><strong>Light &amp; Dark Mode Compliance:</strong><ul><li>All new node controls, effort pills, and <code>KSamplerOutputPreview</code> cards MUST use semantic Tailwind tokens (<code>bg-card</code>, <code>bg-muted/40</code>, <code>text-foreground</code>, <code>text-muted-foreground</code>, <code>border-border</code>, <code>text-brand-orange</code>, <code>bg-brand-orange</code>) and <code>dark:</code> variants passing WCAG AA contrast in both Light and Dark themes.</li></ul></li><li><strong>UI States:</strong><ul><li><strong>Idle:</strong> Shows selected <code>model</code> + <code>effort</code> badges cleanly on <code>generatorNode</code> / <code>modelNode</code> without text truncation.</li><li><strong>Streaming / Sampling:</strong> Displays 4-stage KSampler node progress, live elapsed timer, real expanded prompt snippet, and progressive <code>preview_image</code> frames (real <code>partial_image_b64</code> for Codex; animated denoise canvas for <code>agy</code>/<code>qwen-studio</code>).</li><li><strong>Completed:</strong> Displays final sharp image, progressive denoise strip, provider/model/effort metadata, and standard actions (<code>Save to Library</code>, <code>Write Post</code>, <code>Attach to Task</code>).</li><li><strong>Error:</strong> Clear localized banner (<code>400/401/422/429/502/503</code>) with credit hold released automatically.</li></ul></li></ol><hr><h2 id="_6-api-contract" tabindex="-1">6. API Contract <a class="header-anchor" href="#_6-api-contract" aria-label="Permalink to &quot;6. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/ai/image/models</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiGenerationController</code> → <code>studio_image.py</code> (<code>GET /api/v2/ai/image/models</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/image/studio/generate</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>AiGenerationController</code> → <code>AiCreditGenerationService</code> → <code>studio_image.py</code> (<code>POST /api/v2/ai/image/studio/generate</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/image/studio/generate/stream</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;">Gateway → <code>AiGenerationController</code> SSE proxy → <code>studio_image.py</code> (<code>POST /api/v2/ai/image/studio/generate/stream</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/image/pose-match</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>AiGenerationController</code> → <code>studio_image.py</code> → <code>QwenAmbassadorClient.pose_match</code> (<code>wf2_pose_match.json</code>)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/ai/image/virtual-try-on</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>AiGenerationController</code> → <code>studio_image.py</code> → <code>QwenAmbassadorClient.virtual_try_on</code> (<code>wf3_outfit_change.json</code>)</td></tr></tbody></table><hr><h2 id="_7-error-handling-security-edge-cases" tabindex="-1">7. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_7-error-handling-security-edge-cases" aria-label="Permalink to &quot;7. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Secret Hygiene:</strong> Never log <code>CODEX_OAUTH_ACCESS_TOKEN</code>, <code>~/.codex/auth.json</code>, or <code>agy</code> keyring contents; redact tokens in all structured logs.</li><li><strong>Brain Temp Cleanup (<code>agy</code>):</strong> Always delete <code>~/.gemini/antigravity-cli/brain/&lt;parent_conv_id&gt;</code> and <code>&lt;subagent_conv_id&gt;</code> in <code>finally</code> immediately after reading image bytes into memory.</li><li><strong>Credit Safety:</strong> Reserve <code>1</code> credit unit only after input/safety validation passes; release hold immediately on upstream <code>4xx/5xx/timeout</code> or client abort.</li><li><strong>Concurrency &amp; RAM Guard (<code>mem_limit: 3g</code>):</strong> Enforce <code>asyncio.Semaphore(AGY_MAX_CONCURRENCY)</code> (default <code>1</code>) on <code>agy</code> subprocesses so EC2 <code>brandhub-ai</code> never OOMs alongside PhoBERT/embeddings.</li></ul><hr><h2 id="_8-out-of-scope-deferred" tabindex="-1">8. Out of Scope (Deferred) <a class="header-anchor" href="#_8-out-of-scope-deferred" aria-label="Permalink to &quot;8. Out of Scope (Deferred)&quot;">​</a></h2><ul><li><code>logo-designer/SKILL.md</code> and <code>wf4_logo_product.json</code> (Brand Logo placement workflow — explicitly deferred to a follow-up phase).</li></ul>`,31)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
